import { Contract, GlobalState, abimethod, uint64, bytes, Txn, Global, Uint64, Bytes, assert, Account, itxn, gtxn, clone } from '@algorandfoundation/algorand-typescript'

export class JokePayPerCall extends Contract {
  // Service configuration and accounting
  owner = GlobalState<Account>({ key: 'o' })
  pricePerCall = GlobalState<uint64>({ key: 'p' })
  totalCalls = GlobalState<uint64>({ key: 'tc' })
  totalEarned = GlobalState<uint64>({ key: 'te' })

  /**
   * createApplication
   * Lifecycle method called on contract creation.
   * Initializes the service owner and default pricing.
   */
  public createApplication(): void {
    this.owner.value = Txn.sender
    this.totalCalls.value = Uint64(0)
    this.totalEarned.value = Uint64(0)
    // Default price: 0.005 ALGO = 5000 microALGOs
    this.pricePerCall.value = Uint64(5000)
  }

  /**
   * record_payment
   * Trustless on-chain verification for x402 payments.
   * Expects an atomic group where:
   * gtxn[0]: PaymentTxn (ALGO from user to contract)
   * gtxn[1]: AppCall (this method)
   */
  @abimethod()
  public record_payment(): void {
    // 1. Access the payment transaction at the start of the group
    const payment = gtxn.PaymentTxn(Uint64(0))

    // 2. Security: Verify the payment is actually sent to this contract
    assert(
      payment.receiver === Global.currentApplicationAddress,
      'Payment must be sent to the contract address'
    )

    // 3. Security: Verify the amount covers the current price
    const paidAmount: uint64 = payment.amount
    assert(paidAmount >= this.pricePerCall.value, 'Insufficient payment amount')

    // 4. Accounting: Update global state
    this.totalCalls.value = this.totalCalls.value + Uint64(1)
    this.totalEarned.value = this.totalEarned.value + paidAmount
  }

  /**
   * set_price
   * Allows the owner to update the microALGO cost per joke.
   */
  @abimethod()
  public set_price(newPrice: uint64): void {
    assert(Txn.sender === this.owner.value, 'Only owner can update price')
    this.pricePerCall.value = newPrice
  }

  /**
   * get_stats
   * Returns the total number of jokes served.
   */
  @abimethod()
  public get_stats(): uint64 {
    const calls: uint64 = this.totalCalls.value
    return calls
  }

  /**
   * withdraw
   * Allows the owner to claim accumulated ALGO from the contract.
   */
  @abimethod()
  public withdraw(): void {
    // 1. Authorization check
    assert(Txn.sender === this.owner.value, 'Only owner can withdraw')

    // 2. Balance check
    const amountToWithdraw: uint64 = this.totalEarned.value
    assert(amountToWithdraw > Uint64(0), 'No funds available for withdrawal')

    // 3. Perform inner transaction to send ALGO to owner
    // Fee is set to 0 to utilize fee pooling from the caller
    itxn
      .payment({
        receiver: this.owner.value,
        amount: amountToWithdraw,
        fee: Uint64(0),
      })
      .submit()

    // 4. Reset earnings counter
    this.totalEarned.value = Uint64(0)
  }
}

